  "answer": 0,
  "exp": "1が妥当(堀越事件・2012年)。同判決は、国家公務員法102条1項の「政治的行為」を、公務員の職務遂行の政治的中立性を損なうおそれが実質的に認められるものに限定して解釈し、管理職的地位になく裁量の余地のない職務に従事する職員が、勤務時間外に、国の施設や公務員の地位を利用せず、職務と無関係に行った政党機関紙の配布は構成要件に該当しないとして無罪とした。2: 同判決は限定解釈により罰則規定自体は憲法21条1項等に違反しないとしており、猿払事件判決(1974年)の合憲の結論を変更したものではない。3: 同日の判決(管理職的地位にあった職員の事案)では有罪とされており、勤務時間外・職務外であることのみで一律に処罰の対象外となるわけではない。4: 猿払事件判決(1974年)は、禁止は政治的意見の表明そのものの制約を目的とするものではなく、行動のもたらす弊害の防止を狙いとしたもので、意見表明の自由に対する制約は間接的・付随的なものにとどまるとした。5: 憲法12条は人権保持の努力義務と濫用禁止を定めた一般的・訓示的規定であり、同条を直接の根拠として具体的な権利制限を全面的に導くことはできない。"
