  "answer": 2,
  "exp": "3が妥当(最大判令和2年11月25日)。同判決は、地方議会議員に対する出席停止の懲罰について、議員としての活動を制約するものであり、議会の自律的な権能に基づく判断を尊重すべきとしても司法審査の対象から除かれるものではないとして、出席停止は司法審査の対象とならないとした従来の判例(最大判昭和35年10月19日)を変更した。1: 寄付金返還請求という形式をとっていても、訴訟の帰すうを左右する前提問題として信仰の対象の価値や宗教上の教義に関する判断が必要不可欠であり、紛争の実質がその判断にかかっている場合には、法令の適用による終局的解決が不可能であって法律上の争訟に当たらない(板まんだら事件・最判昭和56年4月7日)。2: 富山大学事件(最判昭和52年3月15日)は、単位授与(認定)行為は原則として司法審査の対象とならないとしたが、専攻科修了の認定については、これを拒否されると学生は専攻科を利用する目的を達せられず一般市民としての権利利益を侵害されるとして、司法審査の対象となるとした。4: 衆議院の解散のように直接国家統治の基本に関する高度に政治性のある国家行為は、たとえ法律上の争訟となり得るものであっても裁判所の審査権の外にある(苫米地事件・最大判昭和35年6月8日)。5: わが国の違憲審査制は付随的審査制であり、具体的な争訟事件が提起されていないのに将来を予想して法令の合憲性を抽象的に判断する権限はない(警察予備隊訴訟・最大判昭和27年10月8日)。",
