  "exp": "2が妥当(最大判昭和38年3月27日・東京都特別区長公選制廃止事件)。同判決は、憲法上の地方公共団体といえるための要件として、住民の共同生活体としての社会的基盤の存在と、相当程度の自主立法権・自主行政権・自主財政権の付与を挙げ、当時の特別区はこれに当たらないとして、区長公選制の廃止は立法政策の問題であり憲法93条2項に違反しないとした。1: 判例は、憲法93条2項の「住民」は地方公共団体の区域内に住所を有する日本国民を意味し、在留外国人には地方選挙権は保障されないとしており、立法によって定住外国人に選挙権を付与することが憲法上禁止されていないとしても、付与しないことが違憲となるものではない(最判平成7年2月28日)。3: 条例は住民の代表機関である議会が民主的手続によって制定するもので法律に類するものであるから、法律による罰則の委任は、政令への委任と異なり、相当程度に具体的で限定されていれば足りる(最大判昭和37年5月30日・大阪市売春取締条例事件)。現行法では地方自治法14条3項が刑の種類と上限を定めており、この要請は満たされている。4: 判例は、財産権の内容について条例による制限を認めている(最大判昭和38年6月26日・奈良県ため池条例事件。ため池の堤とうの使用禁止は財産権の行使のほとんど全面的な制限であっても、災害防止のためやむを得ないものとして条例で定めうるとした)。5: 地方公共団体の課税権は憲法92条・94条に由来し、憲法84条の「法律」には住民の代表機関が定める条例も含まれると解されており、現に地方税法3条は地方税の賦課徴収に関する事項を条例で定めるものとしている。",
